(("undefined"!=typeof globalThis?globalThis:self).makoChunk_antd=("undefined"!=typeof globalThis?globalThis:self).makoChunk_antd||[]).push([["5c014aaa"],{"5c014aaa":function(n,e,t){"use strict";t.d(e,"__esModule",{value:!0}),t.d(e,"texts",{enumerable:!0,get:function(){return a;}}),t("8f787e47");let a=[{value:"\uC11C\uBC84 \uC0AC\uC774\uB4DC \uB80C\uB354\uB9C1 \uC2A4\uD0C0\uC77C\uC5D0\uB294 \uB450\uAC00\uC9C0 \uC635\uC158\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uAC01\uAC01\uC5D0\uB294 \uC7A5\uB2E8\uC810\uC774 \uC874\uC7AC\uD569\uB2C8\uB2E4:",paraId:0},{value:"\uC778\uB77C\uC778 \uBAA8\uB4DC",paraId:1},{value:": \uCD94\uAC00 \uC2A4\uD0C0\uC77C \uD30C\uC77C\uC744 \uB80C\uB354\uB9C1 \uC911\uC5D0 \uC694\uCCAD\uD560 \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uC774 \uBAA8\uB4DC\uB294 \uCD94\uAC00 \uB124\uD2B8\uC6CC\uD06C \uC694\uCCAD\uC744 \uC904\uC774\uB294 \uAC83\uC774 \uC7A5\uC810\uC785\uB2C8\uB2E4. \uB2E8\uC810\uC740 HTML\uC6A9\uB7C9\uC774 \uC99D\uAC00\uD558\uACE0 \uCCAB \uD654\uBA74 \uB80C\uB354\uB9C1\uC758 \uC18D\uB3C4\uC5D0 \uC601\uD5A5\uC744 \uBBF8\uCE60 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAD00\uB828 \uB17C\uC758: ",paraId:1},{value:"#39891",paraId:1},{value:"\uC804\uCCB4 \uB0B4\uBCF4\uB0B4\uAE30(Whole export)",paraId:2},{value:": antd \uCEF4\uD3EC\uB10C\uD2B8\uB294 \uBBF8\uB9AC \uC0DD\uC131\uB41C css\uD30C\uC77C\uB85C \uC2A4\uD0C0\uC77C\uB9C1 \uB418\uC5B4 \uD398\uC774\uC9C0\uC5D0 \uD3EC\uD568\uB429\uB2C8\uB2E4. \uC774 \uBAA8\uB4DC\uB294 \uC5B4\uB5A4 \uD398\uC774\uC9C0\uB97C \uC5F4 \uB54C\uB3C4 \uB3D9\uC77C\uD55C css\uD30C\uC77C \uC138\uD2B8\uAC00 \uC804\uD1B5\uC801\uC778 css\uBC29\uC2DD \uCC98\uB7FC \uCE90\uC2DC\uB418\uC5B4 \uC7AC\uC0AC\uC6A9\uD560 \uC218 \uC788\uB2E4\uB294 \uC7A5\uC810\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uB2E8\uC810\uC740 \uC5EC\uB7EC\uAC1C\uC758 \uD14C\uB9C8\uAC00 \uD55C \uD398\uC774\uC9C0\uC5D0 \uC788\uB294 \uACBD\uC6B0, \uCD94\uAC00\uC801\uC778 \uC2A4\uD0C0\uC77C \uC0DD\uC131\uC774 \uD544\uC694\uD560 \uC218 \uC788\uB2E4\uB294 \uAC83\uC785\uB2C8\uB2E4.",paraId:2},{value:"\uC2A4\uD0C0\uC77C \uCD94\uCD9C\uC744 \uC704\uD574 ",paraId:3,tocIndex:0},{value:"@ant-design/cssinjs",paraId:3,tocIndex:0},{value:"\uB97C \uC0AC\uC6A9\uD558\uC138\uC694:",paraId:3,tocIndex:0},{value:"import React from 'react';\nimport { createCache, extractStyle, StyleProvider } from '@ant-design/cssinjs';\nimport type Entity from '@ant-design/cssinjs/es/Cache';\nimport { renderToString } from 'react-dom/server';\n\nconst App = () => {\n  // SSR \uB80C\uB354\uB9C1\n  const cache = React.useMemo<Entity>(() => createCache(), []);\n  const html = renderToString(\n    <StyleProvider cache={cache}>\n      <MyApp />\n    </StyleProvider>,\n  );\n\n  // \uCE90\uC2DC\uC5D0\uC11C \uC2A4\uD0C0\uC77C \uAC00\uC838\uC624\uAE30\n  const styleText = extractStyle(cache);\n\n  // \uC2A4\uD0C0\uC77C \uD63C\uD569\uC2DC\uD0A4\uAE30\n  return `\n    <!DOCTYPE html>\n    <html>\n      <head>\n        ${styleText}\n      </head>\n      <body>\n        <div id=\"root\">${html}</div>\n      </body>\n    </html>\n  `;\n};\n\nexport default App;\n",paraId:4,tocIndex:0},{value:"css\uD30C\uC77C\uC5D0 \uC2A4\uD0C0\uC77C \uD30C\uC77C\uC744 \uCCA8\uBD80\uD558\uACE0 \uC2F6\uB2E4\uBA74 \uC544\uB798\uC758 \uBC29\uC2DD\uC744 \uC2DC\uB3C4\uD574\uBCF4\uC138\uC694:",paraId:5,tocIndex:1},{value:"\uB514\uD39C\uB358\uC2DC \uC124\uCE58",paraId:6,tocIndex:1},{value:"npm install ts-node tslib cross-env --save-dev\n",paraId:7,tocIndex:1},{value:"tsconfig.node.json",paraId:8,tocIndex:1},{value:"\uD30C\uC77C \uCD94\uAC00",paraId:8,tocIndex:1},{value:'{\n  "compilerOptions": {\n    "strictNullChecks": true,\n    "module": "NodeNext",\n    "jsx": "react",\n    "esModuleInterop": true\n  },\n  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx"]\n}\n',paraId:9,tocIndex:1},{value:"scripts/genAntdCss.tsx",paraId:10,tocIndex:1},{value:"\uD30C\uC77C \uCD94\uAC00",paraId:10,tocIndex:1},{value:"// scripts/genAntdCss.tsx\nimport fs from 'fs';\nimport { extractStyle } from '@ant-design/static-style-extract';\n\nconst outputPath = './public/antd.min.css';\n\nconst css = extractStyle();\n\nfs.writeFileSync(outputPath, css);\n",paraId:11,tocIndex:1},{value:"\uD63C\uD569\uB41C \uD14C\uB9C8\uB098 \uCEE4\uC2A4\uD140 \uD14C\uB9C8\uB97C \uC0AC\uC6A9\uD558\uACE0 \uC2F6\uB2E4\uBA74 \uC544\uB798\uC758 \uC2A4\uD06C\uB9BD\uD2B8\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4:",paraId:12,tocIndex:1},{value:"import fs from 'fs';\nimport React from 'react';\nimport { extractStyle } from '@ant-design/static-style-extract';\nimport { ConfigProvider } from 'antd';\n\nconst outputPath = './public/antd.min.css';\n\nconst testGreenColor = '#008000';\nconst testRedColor = '#ff0000';\n\nconst css = extractStyle((node) => (\n  <>\n    <ConfigProvider\n      theme={{\n        token: {\n          colorBgBase: testGreenColor,\n        },\n      }}\n    >\n      {node}\n    </ConfigProvider>\n    <ConfigProvider\n      theme={{\n        token: {\n          colorPrimary: testGreenColor,\n        },\n      }}\n    >\n      <ConfigProvider\n        theme={{\n          token: {\n            colorBgBase: testRedColor,\n          },\n        }}\n      >\n        {node}\n      </ConfigProvider>\n    </ConfigProvider>\n  </>\n));\n\nfs.writeFileSync(outputPath, css);\n",paraId:13,tocIndex:1},{value:"\uAC1C\uBC1C \uBA85\uB839\uC5B4\uB97C \uC2DC\uC791\uD558\uAE30 \uC804\uC774\uB098 \uCEF4\uD30C\uC77C\uB9C1 \uC774\uC804\uC5D0 \uC774 \uC2A4\uD06C\uB9BD\uD2B8\uB97C \uC2E4\uD589\uD558\uB294 \uC120\uD0DD\uC744 \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uC2A4\uD06C\uB9BD\uD2B8\uB97C \uC2E4\uD589\uD558\uBA74 \uD604\uC7AC \uD504\uB85C\uC81D\uD2B8\uC758 \uBA85\uC2DC\uB41C \uD3F4\uB354(\uC608: public)\uC5D0 \uC644\uC804\uD55C antd.min.css\uD30C\uC77C\uC774 \uC9C1\uC811\uC801\uC73C\uB85C \uC0DD\uC131\uB429\uB2C8\uB2E4. Next.js \uC608\uC81C \uFF08",paraId:14,tocIndex:1},{value:"\uC608\uC81C",paraId:14,tocIndex:1},{value:"\uFF09\uFF1A",paraId:14,tocIndex:1},{value:'// package.json\n{\n  "scripts": {\n    "dev": "next dev",\n    "build": "next build",\n    "start": "next start",\n    "lint": "next lint",\n    "predev": "ts-node --project ./tsconfig.node.json ./scripts/genAntdCss.tsx",\n    "prebuild": "cross-env NODE_ENV=production ts-node --project ./tsconfig.node.json ./scripts/genAntdCss.tsx"\n  }\n}\n',paraId:15,tocIndex:1},{value:"\uADF8\uB9AC\uACE0 ",paraId:16,tocIndex:1},{value:"pages/_app.tsx",paraId:16,tocIndex:1},{value:"\uD30C\uC77C\uC5D0 \uC774 \uD30C\uC77C\uC744 \uBD88\uB7EC\uC624\uBA74 \uB429\uB2C8\uB2E4:",paraId:16,tocIndex:1},{value:"import { StyleProvider } from '@ant-design/cssinjs';\nimport type { AppProps } from 'next/app';\n\nimport '../public/antd.min.css'; // \uC774 \uB77C\uC778\uC744 \uCD94\uAC00\uD558\uC138\uC694\nimport '../styles/globals.css';\n\nexport default function App({ Component, pageProps }: AppProps) {\n  return (\n    <StyleProvider hashPriority=\"high\">\n      <Component {...pageProps} />\n    </StyleProvider>\n  );\n}\n",paraId:17,tocIndex:1},{value:"\uD504\uB85C\uC81D\uD2B8\uC5D0 \uCEE4\uC2A4\uD140 \uD14C\uB9C8\uB97C \uC0AC\uC6A9\uD558\uACE0 \uC788\uB2E4\uBA74, \uB2E4\uC74C \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uD574\uBCF4\uC138\uC694:",paraId:18,tocIndex:2},{value:"import { extractStyle } from '@ant-design/static-style-extract';\nimport { ConfigProvider } from 'antd';\n\nconst cssText = extractStyle((node) => (\n  <ConfigProvider\n    theme={{\n      token: {\n        colorPrimary: 'red',\n      },\n    }}\n  >\n    {node}\n  </ConfigProvider>\n));\n",paraId:19,tocIndex:2},{value:"\uD504\uB85C\uC81D\uD2B8\uC5D0 \uD63C\uD569 \uD14C\uB9C8\uB97C \uC0AC\uC6A9\uD558\uACE0 \uC788\uB2E4\uBA74, \uB2E4\uC74C \uBC29\uC2DD\uC73C\uB85C \uC801\uC6A9\uD574\uBCF4\uC138\uC694:",paraId:20,tocIndex:3},{value:"import { extractStyle } from '@ant-design/static-style-extract';\nimport { ConfigProvider } from 'antd';\n\nconst cssText = extractStyle((node) => (\n  <>\n    <ConfigProvider\n      theme={{\n        token: {\n          colorBgBase: 'green ',\n        },\n      }}\n    >\n      {node}\n    </ConfigProvider>\n    <ConfigProvider\n      theme={{\n        token: {\n          colorPrimary: 'blue',\n        },\n      }}\n    >\n      <ConfigProvider\n        theme={{\n          token: {\n            colorBgBase: 'red ',\n          },\n        }}\n      >\n        {node}\n      </ConfigProvider>\n    </ConfigProvider>\n  </>\n));\n",paraId:21,tocIndex:3},{value:"static-style-extract\uC5D0 \uB300\uD574 \uB354 \uC54C\uACE0 \uC2F6\uB2E4\uBA74, ",paraId:22,tocIndex:3},{value:"static-style-extract",paraId:22,tocIndex:3},{value:"\uC744 \uCC38\uACE0\uD574\uC8FC\uC138\uC694.",paraId:22,tocIndex:3},{value:"// scripts/genAntdCss.tsx\nimport { createHash } from 'crypto';\nimport fs from 'fs';\nimport path from 'path';\nimport { extractStyle } from '@ant-design/cssinjs';\nimport type Entity from '@ant-design/cssinjs/lib/Cache';\n\nexport type DoExtraStyleOptions = {\n  cache: Entity;\n  dir?: string;\n  baseFileName?: string;\n};\nexport function doExtraStyle({\n  cache,\n  dir = 'antd-output',\n  baseFileName = 'antd.min',\n}: DoExtraStyleOptions) {\n  const baseDir = path.resolve(__dirname, '../../static/css');\n\n  const outputCssPath = path.join(baseDir, dir);\n\n  if (!fs.existsSync(outputCssPath)) {\n    fs.mkdirSync(outputCssPath, { recursive: true });\n  }\n\n  const css = extractStyle(cache, true);\n  if (!css) return '';\n\n  const md5 = createHash('md5');\n  const hash = md5.update(css).digest('hex');\n  const fileName = `${baseFileName}.${hash.substring(0, 8)}.css`;\n  const fullpath = path.join(outputCssPath, fileName);\n\n  const res = `_next/static/css/${dir}/${fileName}`;\n\n  if (fs.existsSync(fullpath)) return res;\n\n  fs.writeFileSync(fullpath, css);\n\n  return res;\n}\n",paraId:23,tocIndex:4},{value:"\uC704\uC758 ",paraId:24,tocIndex:4},{value:"_document.tsx",paraId:24,tocIndex:4},{value:"\uC758 \uB3C4\uAD6C\uB97C \uC0AC\uC6A9\uD558\uC5EC \uD544\uC694\uC5D0 \uB530\uB978 \uB0B4\uBCF4\uB0B4\uAE30\uB97C \uD558\uC138\uC694",paraId:24,tocIndex:4},{value:"// _document.tsx\nimport { createCache, StyleProvider } from '@ant-design/cssinjs';\nimport type { DocumentContext } from 'next/document';\nimport Document, { Head, Html, Main, NextScript } from 'next/document';\n\nimport { doExtraStyle } from '../scripts/genAntdCss';\n\nexport default class MyDocument extends Document {\n  static async getInitialProps(ctx: DocumentContext) {\n    const cache = createCache();\n    let fileName = '';\n    const originalRenderPage = ctx.renderPage;\n    ctx.renderPage = () =>\n      originalRenderPage({\n        enhanceApp: (App) => (props) => (\n          <StyleProvider cache={cache}>\n            <App {...props} />\n          </StyleProvider>\n        ),\n      });\n\n    const initialProps = await Document.getInitialProps(ctx);\n    // 1.1 \uC0AC\uC6A9\uB41C \uC2A4\uD0C0\uC77C \uCD94\uCD9C\n    fileName = doExtraStyle({\n      cache,\n    });\n    return {\n      ...initialProps,\n      styles: (\n        <>\n          {initialProps.styles}\n          {/* 1.2 css \uC8FC\uC785 */}\n          {fileName && <link rel=\"stylesheet\" href={`/${fileName}`} />}\n        </>\n      ),\n    };\n  }\n\n  render() {\n    return (\n      <Html lang=\"en\">\n        <Head />\n        <body>\n          <Main />\n          <NextScript />\n        </body>\n      </Html>\n    );\n  }\n}\n",paraId:25,tocIndex:4},{value:"\uB370\uBAA8\uB294 \uC5EC\uAE30\uC11C \uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4:",paraId:26,tocIndex:4},{value:"\uD544\uC694\uC5D0 \uB530\uB978 css\uD30C\uC77C \uB0B4\uBCF4\uB0B4\uAE30 \uB370\uBAA8",paraId:26,tocIndex:4}];}}]);